UPDATE lessons SET title='Year 7, Week 36, Lesson 2: Research and hypothesis', data=json_patch(data,'{"child_mission":"Year 7 science develops research and hypothesis using scientific models, school-safe practical skills and evidence-based conclusions. State the question or idea, apply a clear method or explanation, record observations with units and link claims to evidence. Catalogue alignment uses SC4-WS-01; content-point mapping remains pending.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nPlan one school-safe investigation step for research and hypothesis with variables and safety.\n\nFEEDBACK\nStrong answer: fair-test logic clear; safety practical.\n\nWATCH FOR\nChanging multiple variables or skipping risk controls.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nIndependently complete a task on research and hypothesis: produce notes/diagrams/data as appropriate, include evidence-linked claims, follow safety rules, and write a five-sentence reflection with one next science skill goal.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science","learning_intention":"Year 7 science develops research and hypothesis using scientific models, school-safe practical skills and evidence-based conclusions. State the question or idea, apply a clear method or explanation, record observations with units and link claims to evidence. Catalogue alignment uses SC4-WS-01; content-point mapping remains pending.","lesson_number":2,"lesson_role":"Apply and analyse","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["SC4-WS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Independently complete a task on research and hypothesis: produce notes/diagrams/data as appropriate, include evidence-linked claims, follow safety rules, and write a five-sentence reflection with one next science skill  Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new object/context, two named observations, claim about research and hypothesis linked to that evidence.\n\nParent: Written model 2: Sample misconception: Changing multiple variables or skipping risk controls.. Correction: Strong answer: fair-test logic clear; with evidence.\n\nParent: Likely misconception: Changing multiple variables or skipping risk controls. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses research and hypothesis. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about research and hypothesis, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Accept a new example with named observations and a claim–evidence link about research and hypothesis. Reject title-only labels with no observation. / Accept a misconception plus corrected claim and evidence reason for research and hypothesis. Reject wording changes that leave the same error..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":3,"explanation":"This matches the taught method for research and hypothesis. The other choices miss a key step or use a common mistake.","options":["Changing multiple variables or skipping risk controls","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson","fair-test logic clear; safety practical"],"question":"Plan one school-safe investigation step for research and hypothesis with variables and safety. Which response is most accurate?","type":"multiple_choice"},{"correct_index":0,"explanation":"This is the misconception to avoid for research and hypothesis; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Changing multiple variables or skipping risk controls","Year 7 science develops research and hypothesis using scientific models, school-safe practical skills and","fair-test logic clear; safety practical","Careful use of evidence and explain why it matters with clear evidence"],"question":"Which statement is a common mistake when working with research and hypothesis?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and a named evidence and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Name evidence and explain why it matters only, without linking it to research and hypothesis","Apply research and hypothesis to new material and name the evidence and explain why it matters used","Repeat the worked example wording with no new evidence","Changing multiple variables or skipping risk controls"],"question":"Which response best applies research and hypothesis with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"Trustworthy science claims rest on observable evidence linked to the claim. The other choices miss a key step or use a common mistake.","options":["Copy a label from the lesson title with no observation","Changing multiple variables or skipping risk controls","Use observable features or measurements as evidence, not appearance alone","Decide from which object looks most exciting"],"question":"New examples: steam from a kettle, a germinating bean, a plastic dinosaur, a granite pebble. Which claim about research and hypothesis is most trustworthy?","type":"multiple_choice"},{"correct_index":2,"explanation":"Science claims need named observations linked to the claim. The other choices miss a key step or use a common mistake.","options":["A label copied from the title with no evidence","Changing multiple variables or skipping risk controls","A named observation plus how it supports the claim","A longer story with no observation"],"question":"Which record best supports a science claim about research and hypothesis?","type":"multiple_choice"},{"correct_index":3,"explanation":"The strongest choice applies the taught idea about research and hypothesis with evidence. The other choices miss a key step or use a common mistake.","options":["Changing multiple variables or skipping risk controls","Change several conditions at once so something happens faster","Ignore measurements and decide by which looks nicer","fair-test logic clear; safety practical"],"question":"Using this science idea — Year 7 science develops research and hypothesis using scientific models, school-safe practical — which choice is strongest?","type":"multiple_choice"},{"correct_index":0,"explanation":"Fair tests change one variable, control the rest, and use recorded evidence. The other choices miss a key step or use a common mistake.","options":["Identify the independent variable, control the rest, and record repeatable measurements","Change several conditions at once so something happens faster","Stop early when you like the first result","Ignore measurements and decide by which looks nicer"],"question":"Which investigation design best tests an idea about research and hypothesis?","type":"multiple_choice"},{"correct_index":2,"explanation":"Scientific predictions stay open to new observations rather than protecting a first guess. The other choices miss a key step or use a common mistake.","options":["Changing multiple variables or skipping risk controls","Results that disagree with the first guess should be discarded","If the observed feature changes, the claim about research and hypothesis should change with it","Any exciting story about the object must be true"],"question":"Which prediction about research and hypothesis can be checked with evidence?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept a new example with named observations and a claim–evidence link about research and hypothesis. Reject title-only labels with no observation.","question":"Investigate or describe a fresh example (not the worked objects) that uses research and hypothesis. Record evidence and explain how it supports your claim.","sample_answer":"Sample: new object/context, two named observations, claim about research and hypothesis linked to that evidence.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception plus corrected claim and evidence reason for research and hypothesis. Reject wording changes that leave the same error.","question":"Name one science misconception about research and hypothesis, correct it with evidence, and say why the correction works.","sample_answer":"Sample misconception: Changing multiple variables or skipping risk controls.. Correction: Strong answer: fair-test logic clear; with evidence.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s4-sci-y7-w36-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S4","stage_hints":{"accept":["Today you will practise research and hypothesis.","Read the mission before you start observing or testing.","Keep the property or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations.","Say what each observation shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Working Scientifically","success_criteria":["I can use research and hypothesis with a specific example from this lesson.","I can identify evidence and explain why it matters.","I can practise safety independently on a new prompt.","I can notice model needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"Year 7 science develops research and hypothesis using scientific models, school-safe practical skills and evidence-based conclusions.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Year 7 science develops research and hypothesis using scientific models, school-safe practical skills and"],"question":"Which choice best applies this lesson idea about research and hypothesis with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample for Research and hypothesis: write a testable question, name IV/DV/controls and a safety control before collecting data.\n\nTRY FIRST\nPlan one school-safe investigation step for research and hypothesis with variables and safety.\n\nFEEDBACK\nStrong answer: fair-test logic clear; safety practical.","explain":"Year 7 science develops research and hypothesis using scientific models, school-safe practical skills and evidence-based conclusions. State the question or idea, apply a clear method or explanation, record observations with units and link claims to evidence. Catalogue alignment uses SC4-WS-01; content-point mapping remains pending.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing multiple variables or skipping risk controls. Correct the claim or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Research and hypothesis.","caption":"Link claim to evidence.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Idea</text><text x=\"28\" y=\"78\">science concept</text><text x=\"358\" y=\"42\">Evidence</text><text x=\"358\" y=\"78\">data/obs</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation matters most.","who":"pip"},{"text":"Name the observations, properties or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Example for Research and hypothesis: write a testable question, name IV/DV/controls and a safety control before collecti Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation matters most.\nJuno: Name the observations, properties or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Example for Research and hypothesis: write a testable question, name IV/DV/controls and a safety control before collecti Then write your own evidence."}}]},{"check":{"correct_index":2,"explanation":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.","options":["A guess with no evidence","A claim unrelated to the observation or test","Make the science idea visible: name the observation, source or example you used and say why it supports the claim","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about research and hypothesis with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample for Research and hypothesis: write a testable question, name IV/DV/controls and a safety control before collecting data. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show science thinking. Correct the claim or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"Science habits.","caption":"Models help explain.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Safety</text><text x=\"28\" y=\"78\">school-safe</text><text x=\"358\" y=\"42\">Reflect</text><text x=\"358\" y=\"78\">next skill</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally incorrect claim as a comparison.","options":["A guess with no evidence","A claim unrelated to the observation or test","Use an intentionally incorrect claim as a comparison","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about research and hypothesis with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nChanging multiple variables or skipping risk controls. Here is a more productive model: Example for Research and hypothesis: write a testable question, name IV/DV/controls and a safety control before collecting data.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nStrong answer: fair-test logic clear; safety practical.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Changing multiple variables or skipping risk controls. Correct the claim or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the same science idea on a new place, person, source or context, not a copy of the worked example.","options":["A guess with no evidence","A claim unrelated to the observation or test","Use the same science idea on a new place, person, source or context, not a copy of the worked example","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about research and hypothesis with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nYear 7 science develops research and hypothesis using scientific models, school-safe practical skills and evidence-based conclusions. State the question or idea, apply a clear method or explanation, record observations with units and link claims to evidence. Catalogue alignment uses SC4-WS-01; content-point mapping remains pending. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different evidence.","explain":"Use the same science idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 7, Week 36, Lesson 2: Research and hypothesis","unit_number":8,"unit_title":"Science investigation project","week":36,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample for Research and hypothesis: write a testable question, name IV/DV/controls and a safety control before collecting data.\n\nWrite what makes this example accurate, naming the observations, properties or test steps used.","worked_visuals":[{"alt":"Research and hypothesis.","caption":"Link claim to evidence.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Idea</text><text x=\"28\" y=\"78\">science concept</text><text x=\"358\" y=\"42\">Evidence</text><text x=\"358\" y=\"78\">data/obs</text></g></svg>"},{"alt":"Science habits.","caption":"Models help explain.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Safety</text><text x=\"28\" y=\"78\">school-safe</text><text x=\"358\" y=\"42\">Reflect</text><text x=\"358\" y=\"78\">next skill</text></g></svg>"}],"year_level":"Year 7"}') WHERE seed_key='s4-sci-y7-w36-l2' AND family_id IS NULL;
